settings.shader_text:
// pixelation (obs-shaderfilter)
uniform float Target_Width<
    string widget_type = "slider";
    float minimum = 2.0;
    float maximum = 2000.0;
    float step = 1.0;
> = 320.0;
uniform float Target_Height<
    string widget_type = "slider";
    float minimum = 2.0;
    float maximum = 2000.0;
    float step = 1.0;
> = 180.0;
float4 mainImage(VertData v_in) : TARGET
{
    int px = max(1, int(uv_size.x / max(Target_Width, 2.0)));
    int py = max(1, int(uv_size.y / max(Target_Height, 2.0)));
    int x = int(v_in.uv.x * uv_size.x);
    int y = int(v_in.uv.y * uv_size.y);
    float2 t;
    t.x = (float(x / px) * float(px) + float(px) / 2.0) / uv_size.x;
    t.y = (float(y / py) * float(py) + float(py) / 2.0) / uv_size.y;
    return image.Sample(textureSampler, t);
}
